
SET IDENTITY_INSERT [QuickSqlOrder] ON; MERGE INTO [QuickSqlOrder] WITH (HOLDLOCK) AS [t0] USING (VALUES (@p0, @p1, @p2, @p3, @p4, @p5, @p6, @p7), (@p8, @p9, @p10, @p11, @p12, @p13, @p14, @p15)) AS [qsrc] ([CustomerName], [CustomerId], [Amount], [State], [CreatedAt], [PaidAt], [Note], [Id]) ON ([t0].[Id] = [qsrc].[Id]) WHEN MATCHED THEN UPDATE SET [t0].[CustomerName] = [qsrc].[CustomerName], [t0].[CustomerId] = [qsrc].[CustomerId], [t0].[Amount] = [qsrc].[Amount], [t0].[State] = [qsrc].[State], [t0].[CreatedAt] = [qsrc].[CreatedAt], [t0].[PaidAt] = [qsrc].[PaidAt], [t0].[Note] = [qsrc].[Note] WHEN NOT MATCHED THEN INSERT ([CustomerName], [CustomerId], [Amount], [State], [CreatedAt], [PaidAt], [Note], [Id]) VALUES ([qsrc].[CustomerName], [qsrc].[CustomerId], [qsrc].[Amount], [qsrc].[State], [qsrc].[CreatedAt], [qsrc].[PaidAt], [qsrc].[Note], [qsrc].[Id]); SET IDENTITY_INSERT [QuickSqlOrder] OFF
